module tb;
  reg t_i0, t_i1, t_s;
  wire t_y;
  mux_df DUT (.I0(t_i0), .I1(t_i1), .S(t_s), .Y(t_y));
  integer i, err = 0;
  initial begin
    for (i = 0; i < 8; i = i + 1) begin
      {t_i0, t_i1, t_s} = i[2:0];
      #5;
      if (t_y !== (t_s ? t_i1 : t_i0)) begin
        $display("FAIL: I0=%b I1=%b S=%b got Y=%b", t_i0, t_i1, t_s, t_y);
        err = err + 1;
      end
    end
    if (err == 0) $display("ALL_MUX_DF_TESTS_PASSED");
    $finish;
  end
endmodule
