printf '`timescale 1ns/1ps
module tb;
  reg [1:0] A, B;
  wire GT, LT, EQ;
  comp2 DUT (.A(A), .B(B), .GT(GT), .LT(LT), .EQ(EQ));
  integer i, j, err = 0;
  reg exp_gt, exp_lt, exp_eq;
  initial begin
    for (i = 0; i < 4; i = i + 1) begin
      for (j = 0; j < 4; j = j + 1) begin
        A = i[1:0]; B = j[1:0];
        exp_gt = (i > j);
        exp_lt = (i < j);
        exp_eq = (i == j);
        #5;
        if ({GT, LT, EQ} !== {exp_gt, exp_lt, exp_eq}) begin
          $display("FAIL: A=%0d B=%0d got GT=%b LT=%b EQ=%b expected GT=%b LT=%b EQ=%b", i, j, GT, LT, EQ, exp_gt, exp_lt, exp_eq);
          err = err + 1;
        end
      end
    end
    if (err == 0) $display("ALL_COMP2_TESTS_PASSED");
    $finish;
  end
endmodule
