printf '`timescale 1ns/1ps
module tb;
  reg [3:0] a, b;
  reg op;
  wire [3:0] result;
  alu DUT (.a(a), .b(b), .op(op), .result(result));
  integer err = 0;
  reg [3:0] exp_res;
  initial begin
    // Test 1: Addition
    a = 4\x27d5; b = 4\x27d3; op = 1\x27b0;
    #5; exp_res = (a + b) & 4\x27hF;
    if (result !== exp_res) begin $display("FAIL Add 5+3: got %0d expected %0d", result, exp_res); err = err + 1; end
    // Test 2: Sensitivity list check (toggle op only)
    op = 1\x27b1;
    #5; exp_res = (a - b) & 4\x27hF;
    if (result !== exp_res) begin $display("FAIL Sub 5-3 (op toggle): got %0d expected %0d", result, exp_res); err = err + 1; end
    // Test 3: Subtraction back-to-back dependency chain check
    a = 4\x27d8; b = 4\x27d2; op = 1\x27b1;
    #5; exp_res = (a - b) & 4\x27hF;
    if (result !== exp_res) begin $display("FAIL Sub 8-2: got %0d expected %0d", result, exp_res); err = err + 1; end
    // Test 4: Subtraction negative result (modulo 16)
    a = 4\x27d3; b = 4\x27d7; op = 1\x27b1;
    #5; exp_res = (a - b) & 4\x27hF;
    if (result !== exp_res) begin $display("FAIL Sub 3-7: got %0d expected %0d", result, exp_res); err = err + 1; end
    if (err == 0) $display("ALL_ALU_TESTS_PASSED");
    $finish;
  end
endmodule
' > labs/lab02/task5/tb_grade.v && ./scripts/compile.sh lab02 task5 labs/lab02/task5/tb_grade.v
